(7735971, 1275165, 83313, '<td valign="top">Almost looks like there is reflection going on here, but there isn''t. Cool architecture.</td>', 'Almost looks like there is reflection going on here, but there isn''t. Cool architecture.', '2023-01-02 16:21:22.000000', NULL, 1),
(7735972, 1275309, 83313, '<td valign="top">I love the way the light silhouettes the lines of trees along the ridges. I might have cloned out the transmission tower in the lower left. It''s nothing major, but it did grab my eye.</td>', 'I love the way the light silhouettes the lines of trees along the ridges. I might have cloned out the transmission tower in the lower left. It''s nothing major, but it did grab my eye.', '2023-01-02 17:43:37.000000', NULL, 1),
